      "留守的农民夫妇": "남아 있는 농부 부부",
      "别紧张，年轻人。那些熊没有杀害这里的人。它们来到农场后，只把原来的村民赶去了王城方向。": "진정하게, 젊은이. 저 곰들은 여기서 아무도 죽이지 않았어. 농장에 왔을 때 원래 마을 사람들을 왕도 쪽으로 쫓아냈을 뿐이지.",
      "我们留下，是因为没有从它们身上感到敌意。最初它们连犁怎么扶都不知道，只会用蛮力把田翻得乱七八糟。": "우리가 남은 건 그 녀석들한테서 적의를 느끼지 못했기 때문이야. 처음엔 쟁기 잡는 법도 몰라서 힘으로만 밭을 엉망으로 뒤집어 놓았지.",
      "后来我们教熊男修水渠、播麦种，也教熊娘照料蜂箱和收割。它们学得很慢，但从不糟蹋粮食。": "그 뒤로 우리는 곰 사내들에게 수로 고치는 법과 밀 씨 뿌리는 법을, 곰 아가씨들에게 벌통 돌보는 법과 수확을 가르쳤어. 배우는 건 느려도 곡식을 함부로 한 적은 한 번도 없다네.",
      "它们会在谷仓里给幼熊留出最暖的位置，也会把第一袋新麦送到我们门口。至少在我们眼里，它们没有传闻中那么可恶。": "헛간에서는 새끼 곰들에게 가장 따뜻한 자리를 비워 두고, 햇밀 첫 자루는 우리 집 문 앞까지 가져다준다네. 적어도 우리 눈에는 소문처럼 몹쓸 녀석들이 아니야.",
      "若你一定要继续往前，就亲眼看看再作判断吧。这里发生的事，也许并不是简单的怪物占领村庄。": "기어이 더 나아가겠다면, 직접 눈으로 보고 판단하게. 여기서 일어난 일은 그저 괴물이 마을을 점령한 이야기가 아닐지도 모르니까.",
