      "四位魅魔军官拒绝撤离，以20点攻击力立即展开反击；小队将被杀退，但第五关仍会按通关结算。": "네 명의 서큐버스 장교가 철수를 거부하고 공격력 20으로 즉시 반격합니다. 소대는 격퇴되지만 제5장은 여전히 클리어로 정산됩니다.",
