      "千枝城反击开始：四名魅魔军官依次以20点攻击杀向小队。": "천가지성 반격 시작: 네 명의 서큐버스 장교가 공격력 20으로 차례차례 소대를 덮칩니다.",
      "四名军官的攻势击穿战线，魔族联军先遣队随即越过裂隙接管废墟；小队被迫撤出千枝城。": "네 장교의 공세가 전선을 뚫고, 마족 연합군 선발대가 균열을 넘어 폐허를 장악했습니다. 소대는 천가지성에서 물러날 수밖에 없었습니다.",
      "四位魅魔军官击溃了小队，但银灰狼女猎手已经被击败：第五关剧情完成，全部战利品与通关奖励照常结算。": "네 명의 서큐버스 장교가 소대를 무너뜨렸지만, 은회색 늑대 여사냥꾼은 이미 쓰러졌습니다. 제5장 스토리가 완료되었고 모든 전리품과 클리어 보상은 평소대로 정산됩니다.",
