      "64名英雄使用相同卡池展开六轮淘汰赛，对手卡牌等级每场随机。": "영웅 64명이 같은 카드 풀로 6라운드 토너먼트를 치릅니다. 상대의 카드 레벨은 경기마다 무작위입니다.",
      "王冠杯 · 64强": "왕관배 · 64강",
      "晋级奖金：32强100金币、16强200、8强400、4强800、亚军1200、冠军1600。": "진출 상금: 32강 100골드, 16강 200, 8강 400, 4강 800, 준우승 1200, 우승 1600.",
