      "已加入英雄技能收藏，可在英雄档案装备。": "영웅 기술 컬렉션에 추가되었습니다. 영웅 기록에서 장착할 수 있습니다.",
      "，你成为本届王冠杯冠军！": ", 당신이 이번 왕관배 우승자입니다!",
