      "商人将货物摊在褪色的毯子上。每件货物每次造访只能购买一次。": "상인이 빛바랜 담요 위에 물건을 펼쳐 놓았습니다. 각 물건은 방문할 때마다 한 번만 살 수 있습니다.",
