      "第五关存档调整": "제5장 저장 조정",
      "只留下最终首领？": "최종 보스만 남길까요?",
      "将第五关设置为前19个首领已经击败，只留下银灰狼女猎手。英雄、金币、收藏、卡组以及其他关卡存档均不会改变。": "제5장을 처음 19명의 보스를 이미 쓰러뜨린 상태로 만들고, 은회색 늑대 여사냥꾼만 남깁니다. 영웅, 골드, 컬렉션, 덱과 다른 장의 저장은 바뀌지 않습니다.",
      "确认调整": "조정 확인",
      "存档已删除并重建。": "저장 데이터를 삭제하고 새로 만들었습니다.",
      "第五关已调整：前19个首领已击败，只剩最终首领。": "제5장 조정 완료: 처음 19명의 보스를 쓰러뜨렸고 최종 보스만 남았습니다.",
      "哥布林王庭 · 第{0}关": "고블린 왕궁 · 제{0}스테이지",
      "金麦农场 · 第{0}关": "황금밀 농장 · 제{0}스테이지",
      "梦幻森林 · 第{0}关": "몽환의 숲 · 제{0}스테이지",
      "古城废墟 · 第{0}关": "옛 도시 폐허 · 제{0}스테이지",
      "{0} · 统领试炼第{1}关": "{0} · 통솔자의 시련 제{1}시련",
      "盖文发动「坚守」：召唤{0}个1/9训练傀儡，并自动失去5点生命（已坚持{1}/7轮）。": "개빈이 '굳건한 수비' 발동: 1/9 훈련 인형 {0}개를 소환하고 체력을 5 잃었습니다({1}/7라운드 버팀).",
      "亚瑟兰发动「天穹一闪」，命中{0}，造成10点伤害（已坚持{1}/15轮）。": "에테르란이 '천궁일섬' 발동: {0}에게 적중해 피해를 10 주었습니다({1}/15라운드 버팀).",
      "女王的低语（{0}/{1}）：{2}": "여왕의 속삭임({0}/{1}): {2}",
      "{0}/7回合": "{0}/7턴",
      "{0}/15回合": "{0}/15턴",
      "{0}/{1}段": "{0}/{1}절",
      "第{0}关 · {1}": "제{0}시련 · {1}",
      "有人说{0}永远不可能被人类接纳。可我的军籍、薪饷和选票都是真的。": "{0}은(는) 결코 인간에게 받아들여질 수 없다고 말하는 이들도 있다. 하지만 내 군적도, 급여도, 투표권도 모두 진짜다.",
      "记住报名册上的名字——{0}。我来自{1}，也认同人类建立的{2}；所以我选择加入，他们也接受了我。": "명단의 이름을 기억해라, {0}. 나는 {1} 출신이고, 인간이 세운 {2}에도 공감한다. 그래서 합류를 택했고, 그들도 나를 받아들였다.",
      "记好名字，{0}。{1}。等你退场时，至少知道是谁送你的。": "이름을 기억해 둬, {0}. {1}. 퇴장할 때 누가 널 보냈는지 정도는 알아야지.",
      "我是{0}，来自{1}。我的研究是{2}；而你，是今天最有价值的实战样本。": "나는 {1} 출신의 {0}. 내 연구는 {2}. 그리고 너는 오늘 가장 가치 있는 실전 표본이야.",
      "我是{0}，来自{1}。我信奉{2}。护卫队长，请用一场完整的战斗回应我。": "나는 {1} 출신의 {0}이다. 나는 {2}을(를) 믿는다. 호위대장, 온전한 한 판의 전투로 내게 답해 다오.",
      "并对同路后排造成{0}点伤害": ", 같은 라인의 후열에도 피해를 {0} 줍니다",
      "同时对敌方英雄造成{0}点伤害": ", 동시에 적 영웅에게 피해를 {0} 줍니다",
      "为英雄恢复{0}点生命": "영웅의 체력을 {0} 회복",
      "对一个敌方前排随从造成{0}点伤害{1}。": "적 전열 하수인 하나에게 피해를 {0} 줍니다{1}.",
