      "自己受到{0}点伤害": "자신은 피해를 {0} 받습니다",
      "对敌方英雄造成{0}点伤害{1}。": "적 영웅에게 피해를 {0} 줍니다{1}.",
      "并抽{0}张牌": ", 그리고 카드를 {0}장 뽑습니다",
      "为英雄恢复{0}点生命{1}。": "영웅의 체력을 {0} 회복합니다{1}.",
      "召唤{0}个{1}攻/{2}血的{3}{4}。": "{1}/{2} {3} {0}개를 소환합니다{4}.",
      "，并额外对英雄造成{0}点伤害": ", 그리고 영웅에게 피해를 {0} 더 줍니다",
      "，为自己恢复{0}点生命": ", 자신의 체력을 {0} 회복합니다",
