      "对敌方前排所有随从造成{0}点伤害{1}。": "적 전열의 모든 하수인에게 피해를 {0} 줍니다{1}.",
      "，并抽{0}张牌": ", 그리고 카드를 {0}장 뽑습니다",
      "为受伤最重的己方随从恢复{0}点生命；没有随从时治疗英雄{1}。": "가장 많이 다친 아군 하수인의 체력을 {0} 회복합니다. 하수인이 없으면 영웅을 치유합니다{1}.",
