      "王都竞技场 · {0}": "왕도 투기장 · {0}",
      "{0}使用与你完全相同的卡组，但卡牌等级在本场随机决定。": "{0}은(는) 당신과 완전히 같은 덱을 쓰지만, 이번 경기의 카드 레벨은 무작위로 정해집니다.",
      "遭遇{0}「{1}」。击穿任意一路即可攻击敌方英雄。": "{0} '{1}'와(과) 조우했습니다. 아무 라인이나 뚫으면 적 영웅을 공격할 수 있습니다.",
      "对一个敌方前排随从造成{0}点伤害。": "적 전열 하수인 하나에게 피해를 {0} 줍니다.",
      "{0}牌库耗尽，受到{1}点疲劳伤害，剩余{2}点生命。": "{0}의 덱이 바닥나 탈진 피해를 {1} 받았습니다. 남은 체력 {2}.",
      "{0}的": "{0}의",
      "{0}手牌已满，{1}被弃掉。": "{0} 손패가 가득 차서 {1}이(가) 버려졌습니다.",
