      "{0}本回合已经使用。": "{0}은(는) 이번 턴에 이미 사용했습니다.",
      "{0}为{1}恢复{2}点生命（治疗力{3}），本回合不能再次治疗。": "{0}이(가) {1}의 체력을 {2} 회복했습니다(치유력 {3}). 이번 턴에는 더 치유할 수 없습니다.",
      "{0}仍在伤员名单中，需要先在队伍营地救治。": "{0}은(는) 아직 부상자 명단에 있습니다. 먼저 팀 캠프에서 치료하세요.",
