      "{0}擂响战鼓，其他{1}个友方随从永久获得+2攻击。": "{0}이(가) 전투 북을 울려 다른 아군 하수인 {1}명이 영구적으로 공격력 +2를 얻었습니다.",
      "{0}的龙息": "{0}의 용의 숨결",
