      "{0}唤醒土壤，使{1}个相邻友方随从获得+1/+1。": "{0}이(가) 흙을 깨워 인접한 아군 하수인 {1}명이 +1/+1을 얻었습니다.",
      "{0}献上蜂蜜祝福，为{1}恢复{2}点生命。": "{0}이(가) 꿀의 축복을 바쳐 {1}의 체력을 {2} 회복했습니다.",
