      "{0}献上晨露，为{1}恢复{2}点生命。": "{0}이(가) 아침 이슬을 바쳐 {1}의 체력을 {2} 회복했습니다.",
      "{0}释放泡泉术，为{1}恢复{2}点生命。": "{0}이(가) 거품샘술을 펼쳐 {1}의 체력을 {2} 회복했습니다.",
