      "你施放{0}（{1}费），为{2}恢复{3}点生命，剩余{4}/{5}法力。": "당신은 {0}을(를) 시전해(비용 {1}) {2}의 체력을 {3} 회복했습니다. 남은 마나 {4}/{5}.",
