      "🌾 农垦本能：召唤{0}个熊族随从": "🌾 개간 본능: 곰족 하수인 {0}명 소환",
      "，并使{0}个熊族随从获得+1/+2": ", 그리고 곰족 하수인 {0}명이 +1/+2를 얻었습니다",
      "丰穗战母发动「护田战令」：召唤{0}个5/7丰穗近卫{1}。": "풍요이삭 전쟁어미가 '밭을 지키는 전령' 발동: 5/7 풍요이삭 근위병 {0}명을 소환했습니다{1}.",
      "🐻 护田战令：召唤{0}个丰穗近卫": "🐻 밭을 지키는 전령: 풍요이삭 근위병 {0}명 소환",
      "{0}发动「胶质再生」：首领恢复{1}点生命，{2}个史莱姆随从共恢复{3}点生命。": "{0}이(가) '젤 재생' 발동: 보스가 체력을 {1} 회복하고, 슬라임 하수인 {2}명이 총 {3} 회복했습니다.",
      "，并分裂出{0}个4/12碧露近卫": ", 그리고 4/12 벽로 근위병 {0}명으로 분열했습니다",
      "碧露大贤者发动「不灭胶质」：自身恢复{0}点生命，随从共恢复{1}点生命{2}。": "벽로의 대현자가 '불멸의 젤' 발동: 자신의 체력을 {0}, 하수인이 총 {1} 회복했습니다{2}.",
      "并召唤{0}名近卫": ", 그리고 근위병 {0}명을 소환했습니다",
      "🫧 不灭胶质：恢复{0}": "🫧 불멸의 젤: {0} 회복",
      "{0}现为{1}攻": "{0}의 공격력이 {1}이(가) 되었습니다",
      "{0}个狼类随从永久获得+1攻击（{1}）。": "늑대 하수인 {0}명이 영구적으로 공격력 +1을 얻었습니다({1}).",
      "森林狼王发动「裂月咆哮」：{0}": "숲의 늑대왕이 '찢긴 달의 포효' 발동: {0}",
      "五位魅魔军官撕开空间裂隙：一人带走{0}，其余四人以{1}攻/{2}血的姿态{3}。": "다섯 명의 서큐버스 장교가 공간의 균열을 열었습니다: 한 명은 {0}을(를) 데려가고, 나머지 넷은 {1}/{2}의 모습으로 {3}.",
      "魅魔救援结界维持到第{0}/2回合；四名军官仍站在前排，没有发动攻击。": "서큐버스 구출 결계가 제{0}/2턴까지 유지됩니다. 네 명의 장교는 여전히 전열에 서서 공격하지 않았습니다.",
      "两回合已过，四位魅魔军官一同跃入裂隙，带着{0}撤离战场。": "두 턴이 지나, 네 명의 서큐버스 장교가 함께 균열로 뛰어들어 {0}을(를) 데리고 전장에서 철수했습니다.",
      "{0}个再生随从在回合开始时共恢复{1}点生命。": "재생 하수인 {0}명이 턴 시작 시 총 {1} 회복했습니다.",
      "我方第{0}回合开始：法力恢复为{1}/{2}，场上{3}个随从，手牌{4}张。": "아군 제{0}턴 시작: 마나가 {1}/{2}(으)로 회복, 전장의 하수인 {3}명, 손패 {4}장.",
      "{0}被击败！": "{0}을(를) 쓰러뜨렸습니다!",
