      "{0}费": "비용 {0}",
      "选择一个敌方前排随从施放{0}。": "{0}을(를) 시전할 적 전열 하수인을 선택하세요.",
      "{0}回合": "{0}턴",
      "第{0}回合": "제{0}턴",
      "{0}已被第五名军官救走。四名20攻/200血军官拒绝撤离，正在直接杀退小队。": "{0}은(는) 다섯 번째 장교에게 구출되었습니다. 20/200 장교 넷이 철수를 거부하고 소대를 직접 몰아내고 있습니다.",
      "{0}已被第五名军官带走。四名10攻/200血军官封锁前排，并将在{1}回合后撤离。": "{0}은(는) 다섯 번째 장교에게 끌려갔습니다. 10/200 장교 넷이 전열을 봉쇄하고 {1}턴 뒤 철수합니다.",
      "你的回合 · 第{0}回合": "당신의 턴 · 제{0}턴",
