      "每回合恢复至 {0}/{1}。永久上限不封顶，只能由统领试炼首次通关提升。": "매 턴 {0}/{1}까지 회복합니다. 영구 상한은 제한이 없으며, 통솔자의 시련 첫 클리어로만 올릴 수 있습니다.",
      "{0} 场胜利 · {1} 次通关 · 收藏 {2} 张": "{0}승 · {1}회 클리어 · 카드 {2}장 수집",
