      "✓ 卡组数量正确，可携带24–{0}张牌。": "✓ 덱 매수가 올바릅니다. 24–{0}장을 가져갈 수 있습니다.",
      "{0}张可加入": "{0}장 추가 가능",
      "卡组必须包含24至{0}张牌。": "덱은 24~{0}장이어야 합니다.",
      "重新开始第{0}关？": "제{0}장을 다시 시작할까요?",
      "只会清空第{0}关的节点记录与本关生命状态，其他关卡的独立存档不会受影响。": "제{0}장의 노드 기록과 이 장의 체력 상태만 초기화됩니다. 다른 장의 개별 저장에는 영향이 없습니다.",
      "存档 {0}/{1}": "저장 {0}/{1}",
