      "你抽取{0}张牌{1}（手牌{2}/10，牌库{3}）。": "당신은 카드를 {0}장 뽑았습니다{1}(손패 {2}/10, 덱 {3}).",
      "你装备{0}（{1}费，{2}攻/{3}耐久）{4}；剩余{5}/{6}法力。": "당신은 {0}을(를) 장착했습니다(비용 {1}, {2}/{3}){4}. 남은 마나 {5}/{6}.",
      "你打出{0}（{1}费，剩余{2}/{3}法力），部署到第{4}路{5}，当前{6}攻/{7}血{8}。": "당신은 {0}을(를) 냈습니다(비용 {1}, 남은 마나 {2}/{3}). 제{4}라인 {5}에 배치, 현재 {6}/{7}{8}.",
      "{0}侦察成功：你抽1张牌。": "{0} 정찰 성공: 당신은 카드를 1장 뽑았습니다.",
      "{0}从麦垛中找到补给，你抽1张牌。": "{0}이(가) 짚더미에서 보급품을 찾아 당신은 카드를 1장 뽑았습니다.",
      "“{0}”": "“{0}”",
