      "紫晶魔女": "자수정 마녀",
      "晨曦圣女": "새벽의 성녀",
      "裂角蛮王": "부러진 뿔의 야만왕",
      "银叶游侠": "은빛잎 순찰자",
      "银盾骑士": "은방패 기사",
      "森灵德鲁伊": "숲정령 드루이드",
      "林海边境最年轻的神射手，她的箭能穿过层层枝叶，找到藏在阵后的敌人。": "숲 변경에서 가장 어린 명사수. 그녀의 화살은 겹겹의 나뭇가지를 뚫고 진형 뒤에 숨은 적을 찾아낸다.",
      "离开法塔独自研究裂隙的魔女，擅长把魔力拆成无数枚难以躲避的飞弹。": "마법탑을 떠나 홀로 균열을 연구하는 마녀. 마력을 피하기 힘든 수많은 탄환으로 쪼개는 데 능하다.",
      "太阳神殿派往前线的圣女，相信每一名士兵都值得再站起来一次。": "태양 신전이 전선으로 보낸 성녀. 모든 병사가 다시 일어설 자격이 있다고 믿는다.",
      "北地部族的蛮王，以自己的鲜血点燃战士的怒火。": "북방 부족의 야만왕. 자신의 피로 전사들의 분노에 불을 붙인다.",
      "月林巡林员的首领，总能让敌人在树影里看到不该出现的弓手。": "달숲 순찰대의 우두머리. 적은 언제나 있어서는 안 될 궁수를 나무 그늘 속에서 보게 된다.",
      "王都晨辉骑士团的老兵，他的盾阵从未在他面前后退一步。": "왕도 새벽빛 기사단의 노병. 그의 방패진은 한 걸음도 물러선 적이 없다.",
      "古林之心孕育的德鲁伊，她种下的每一株幼苗都会长成守护森林的古树。": "고대 숲의 심장에서 태어난 드루이드. 그녀가 심은 묘목은 모두 숲을 지키는 고목으로 자란다.",
      "穿林箭": "숲 관통 화살",
      "奥术飞弹": "비전 화살",
      "晨曦复苏": "새벽의 소생",
      "血怒狂击": "피의 광란",
      "林间伏兵": "숲속 매복",
      "圣盾壁垒": "성방패 방벽",
      "萌芽古树": "싹트는 고목",
      "无视前排保护，对任意一个敌方随从造成{0}点伤害；若击杀目标，抽1张牌。": "전열 보호를 무시하고 적 하수인 하나에게 피해를 {0} 줍니다. 대상을 처치하면 카드를 1장 뽑습니다.",
      "发射{0}枚奥术飞弹，每枚随机对一个敌方随从或敌方英雄造成1点伤害。": "비전 화살을 {0}발 발사합니다. 각 화살은 무작위 적 하수인 또는 적 영웅에게 피해를 1 줍니다.",
      "使所有己方随从恢复至满生命，并为英雄恢复{0}点生命。": "모든 아군 하수인의 생명력을 최대로 회복하고 영웅의 생명력을 {0} 회복합니다.",
      "英雄失去2点生命，使一个己方随从本回合获得+{0}攻击，并可以立即再次攻击。": "영웅이 생명력을 2 잃고, 아군 하수인 하나가 이번 턴에 공격력 +{0}을 얻으며 즉시 다시 공격할 수 있습니다.",
      "在后排召唤一个{0}攻/{1}血的远程林影弓手，它可以立即攻击随从。": "후열에 공격력 {0}/생명력 {1}의 원거리 숲그림자 궁수를 소환합니다. 즉시 하수인을 공격할 수 있습니다.",
      "所有己方前排随从永久获得+{0}生命；若前排为空，则召唤一个0攻/{1}血的圣盾卫士。": "모든 아군 전열 하수인이 영구히 생명력 +{0}을 얻습니다. 전열이 비어 있으면 공격력 0/생명력 {1}의 성방패 수호자를 소환합니다.",
      "召唤一个{0}攻/{1}血的古树幼苗；它在你每回合开始时永久获得+1/+1。": "공격력 {0}/생명력 {1}의 고목 묘목을 소환합니다. 내 턴이 시작될 때마다 영구히 +1/+1을 얻습니다.",
      "林影弓手": "숲그림자 궁수",
      "圣盾卫士": "성방패 수호자",
