      "{0}击杀了{1}，你抽1张牌。": "{0}이(가) {1}을(를) 처치했습니다. 카드를 1장 뽑습니다.",
      "{0}枚奥术飞弹命中：{1}。": "비전 화살 {0}발 명중: {1}.",
      "{0}×{1}": "{0}×{1}",
      "晨曦照亮战线：随从共恢复{0}点生命，英雄恢复{1}点生命。": "새벽빛이 전선을 비춥니다: 하수인이 총 {0}, 영웅이 {1}의 생명력을 회복했습니다.",
      "{0}陷入血怒，本回合攻击力提升至{1}，可以立即攻击。": "{0}이(가) 피의 광란에 빠졌습니다. 이번 턴 공격력이 {1}(으)로 오르고 즉시 공격할 수 있습니다.",
      "{0}陷入血怒，本回合攻击力提升至{1}。": "{0}이(가) 피의 광란에 빠졌습니다. 이번 턴 공격력이 {1}(으)로 오릅니다.",
      "圣盾壁垒加固前排：{0}个随从永久获得+{1}生命。": "성방패 방벽이 전열을 강화합니다: 하수인 {0}명이 영구히 생명력 +{1}을 얻었습니다.",
