      "新英雄「{0}」将从头开始远征。之后的进度会自动保存到所选栏位。": "새 영웅 「{0}」이(가) 처음부터 원정을 시작합니다. 이후 진행 상황은 선택한 슬롯에 자동 저장됩니다.",
      "读取后，之后的进度会自动保存到该栏位。": "불러온 뒤의 진행 상황은 해당 슬롯에 자동 저장됩니다.",
      "当前进度会自动保存到当前栏位；“保存到此”会把当前进度另存到所选栏位，并以它作为之后的自动保存栏位。": "진행 상황은 현재 슬롯에 자동 저장됩니다. 「여기에 저장」은 현재 진행을 선택한 슬롯에 따로 저장하고, 이후 자동 저장 슬롯으로 삼습니다.",
      "覆盖栏位{0}？": "슬롯 {0}을(를) 덮어쓸까요?",
      "栏位{0}中{1} Lv{2}的存档将被永久删除，并以新英雄重新开始。": "슬롯 {0}의 {1} Lv{2} 저장이 영구 삭제되고 새 영웅으로 다시 시작합니다.",
      "读取栏位{0}？": "슬롯 {0}을(를) 불러올까요?",
      "当前进度还没有保存到任何栏位，读取后将会丢失。": "현재 진행 상황은 어느 슬롯에도 저장되지 않았으며, 불러오면 사라집니다.",
      "栏位{0}中{1} Lv{2}的存档将被当前进度覆盖。": "슬롯 {0}의 {1} Lv{2} 저장이 현재 진행 상황으로 덮어써집니다.",
      "覆盖保存": "덮어쓰기",
      "删除栏位{0}？": "슬롯 {0}을(를) 삭제할까요?",
      "{0} Lv{1}的存档将被永久删除。": "{0} Lv{1}의 저장이 영구 삭제됩니다.",
      "这是当前存档：删除后当前进度不会再自动保存到任何栏位。": "현재 사용 중인 저장입니다. 삭제하면 이후 진행 상황이 어느 슬롯에도 자동 저장되지 않습니다.",
